        EventDispatcher eventDispatcher = new EventDispatcher();
        EmailService emailService = new EmailService(messageStore);

        eventDispatcher.register(ReservationConfirmedEvent.class, new GuestNotificationHandler(emailService));
        eventDispatcher.register(ReservationConfirmedEvent.class, new HousekeepingNotificationHandler(emailService));
