        app.post("/reservations/{id}/check-in", reservationController::checkIn);
        app.post("/reservations/{id}/check-out", reservationController::checkOut);
        app.get("/reservations/{id}/document", reservationController::getDocument);
        app.get("/messages", messageController::list);
        app.get("/reports/occupancy", reportController::occupancy);
        app.get("/reports/revenue", reportController::revenue);

        app.exception(Exception.class, ErrorHandler::handle);
    }

    @AfterAll
    static void tearDown() {
        if (app != null) {
            app.stop();
        }
    }

    @Test
    void shouldListRooms() {
        JavalinTest.test(app, (server, client) -> {
            var response = client.get("/rooms");
            assertThat(response.code()).isEqualTo(200);
            assertThat(response.body().string()).contains("\"number\":\"101\"");
            assertThat(response.body().string()).contains("\"type\":\"STANDARD\"");
        });
    }

    @Test
    void shouldCreateAndConfirmReservation() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "101",
                    "guestName": "João Silva",
                    "guestEmail": "joao@example.com",
                    "guestCpf": "12345678901",
                    "checkIn": "2027-03-10",
                    "checkOut": "2027-03-12",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
            """;

            var createResponse = client.post("/reservations", requestBody);
            assertThat(createResponse.code()).isEqualTo(201);
            String body = createResponse.body().string();
            assertThat(body).contains("\"status\":\"PENDING\"");
            assertThat(body).contains("\"nights\":2");
            assertThat(body).contains("\"subtotal\":499.80");

            var confirmResponse = client.post("/reservations/1/confirmation", "");
            assertThat(confirmResponse.code()).isEqualTo(200);
            assertThat(confirmResponse.body().string()).contains("\"status\":\"CONFIRMED\"");

            var messagesResponse = client.get("/messages");
            assertThat(messagesResponse.code()).isEqualTo(200);
            String messages = messagesResponse.body().string();
            assertThat(messages).contains("joao@example.com");
            assertThat(messages).contains("governanca@pousadamarealta.com.br");
            assertThat(messages).contains("financeiro@pousadamarealta.com.br");
        });
    }

    @Test
    void shouldCalculateHighSeasonPrices() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "102",
                    "guestName": "Maria Santos",
                    "guestEmail": "maria@example.com",
                    "guestCpf": "98765432100",
                    "checkIn": "2027-07-10",
                    "checkOut": "2027-07-12",
                    "guests": 1,
                    "ratePlan": "STANDARD"
                }
            """;

            var response = client.post("/reservations", requestBody);
            assertThat(response.code()).isEqualTo(201);
            String body = response.body().string();
            assertThat(body).contains("\"nights\":2");
            assertThat(body).contains("\"subtotal\":599.76");
        });
    }

    @Test
    void shouldApplyNonRefundableDiscount() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "201",
                    "guestName": "Pedro Costa",
                    "guestEmail": "pedro@example.com",
                    "guestCpf": "11122233344",
                    "checkIn": "2027-03-10",
                    "checkOut": "2027-03-12",
                    "guests": 3,
                    "ratePlan": "NON_REFUNDABLE"
                }
            """;

            var response = client.post("/reservations", requestBody);
            assertThat(response.code()).isEqualTo(201);
            String body = response.body().string();
            assertThat(body).contains("\"subtotal\":779.80");
            assertThat(body).contains("\"discount\":116.97");
            assertThat(body).contains("\"total\":662.83");
        });
    }

    @Test
    void shouldPreventDoubleBooking() {
        JavalinTest.test(app, (server, client) -> {
            String request1 = """
                {
                    "roomNumber": "301",
                    "guestName": "Ana Lima",
                    "guestEmail": "ana@example.com",
                    "guestCpf": "55566677788",
                    "checkIn": "2027-04-01",
                    "checkOut": "2027-04-05",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
            """;

            var response1 = client.post("/reservations", request1);
            assertThat(response1.code()).isEqualTo(201);

            client.post("/reservations/" + extractId(response1.body().string()) + "/confirmation", "");

            String request2 = """
                {
                    "roomNumber": "301",
                    "guestName": "Carlos Souza",
                    "guestEmail": "carlos@example.com",
                    "guestCpf": "99988877766",
                    "checkIn": "2027-04-03",
                    "checkOut": "2027-04-07",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
            """;

            var response2 = client.post("/reservations", request2);
            assertThat(response2.code()).isEqualTo(409);
            assertThat(response2.body().string()).contains("ROOM_UNAVAILABLE");
        });
    }

    @Test
    void shouldHandleCancellationWithRefund() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "202",
                    "guestName": "Julia Ferreira",
                    "guestEmail": "julia@example.com",
                    "guestCpf": "11223344556",
                    "checkIn": "2027-05-15",
                    "checkOut": "2027-05-17",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
            """;

            var createResponse = client.post("/reservations", requestBody);
            String id = extractId(createResponse.body().string());

            client.post("/reservations/" + id + "/confirmation", "");

            var cancelResponse = client.post("/reservations/" + id + "/cancellation", "");
            assertThat(cancelResponse.code()).isEqualTo(200);
            String body = cancelResponse.body().string();
            assertThat(body).contains("\"status\":\"CANCELLED\"");
            assertThat(body).contains("\"refund\":779.80");

            var messagesResponse = client.get("/messages");
            String messages = messagesResponse.body().string();
            assertThat(messages).contains("Reembolso - reserva " + id);
            assertThat(messages).contains("Reserva cancelada - quarto 202");
        });
    }

    @Test
    void shouldNotRefundNonRefundableCancellation() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "201",
                    "guestName": "Roberto Alves",
                    "guestEmail": "roberto@example.com",
                    "guestCpf": "77788899900",
                    "checkIn": "2027-06-20",
                    "checkOut": "2027-06-22",
                    "guests": 2,
                    "ratePlan": "NON_REFUNDABLE"
                }
            """;

            var createResponse = client.post("/reservations", requestBody);
            String id = extractId(createResponse.body().string());

            client.post("/reservations/" + id + "/confirmation", "");

            var cancelResponse = client.post("/reservations/" + id + "/cancellation", "");
            assertThat(cancelResponse.code()).isEqualTo(200);
            String body = cancelResponse.body().string();
            assertThat(body).contains("\"status\":\"CANCELLED\"");
            assertThat(body).contains("\"refund\":0.00");
        });
    }

    @Test
    void shouldGenerateOccupancyReport() {
        JavalinTest.test(app, (server, client) -> {
            String request1 = """
                {
                    "roomNumber": "101",
                    "guestName": "Test User 1",
                    "guestEmail": "test1@example.com",
                    "guestCpf": "11111111111",
                    "checkIn": "2027-08-01",
                    "checkOut": "2027-08-05",
                    "guests": 1,
                    "ratePlan": "STANDARD"
                }
            """;

            var response1 = client.post("/reservations", request1);
            client.post("/reservations/" + extractId(response1.body().string()) + "/confirmation", "");

            String request2 = """
                {
                    "roomNumber": "102",
                    "guestName": "Test User 2",
                    "guestEmail": "test2@example.com",
                    "guestCpf": "22222222222",
                    "checkIn": "2027-08-01",
                    "checkOut": "2027-08-03",
                    "guests": 2,
                    "ratePlan": "STANDARD"
                }
            """;

            var response2 = client.post("/reservations", request2);
            client.post("/reservations/" + extractId(response2.body().string()) + "/confirmation", "");

            var reportResponse = client.get("/reports/occupancy?date=2027-08-01");
            assertThat(reportResponse.code()).isEqualTo(200);
            String csv = reportResponse.body().string();
            assertThat(csv).contains("room,type,reservation,check_in,check_out");
            assertThat(csv).contains("101,STANDARD");
            assertThat(csv).contains("102,STANDARD");
            assertThat(csv).contains("total,2/5");
        });
    }

    @Test
    void shouldGenerateRevenueReport() {
        JavalinTest.test(app, (server, client) -> {
            String requestBody = """
                {
                    "roomNumber": "301",
                    "guestName": "Revenue Test",
                    "guestEmail": "revenue@example.com",
                    "guestCpf": "33333333333",
                    "checkIn": "2027-09-15",
                    "checkOut": "2027-09-17",
                    "guests": 3,
                    "ratePlan": "STANDARD"
                }
            """;

            var createResponse = client.post("/reservations", requestBody);
            client.post("/reservations/" + extractId(createResponse.body().string()) + "/confirmation", "");

            var reportResponse = client.get("/reports/revenue?month=2027-09");
            assertThat(reportResponse.code()).isEqualTo(200);
            String csv = reportResponse.body().string();
            assertThat(csv).contains("reservation,room,check_in,check_out,status,amount");
            assertThat(csv).contains("301");
            assertThat(csv).contains("2027-09-15");
            assertThat(csv).contains("CONFIRMED");
        });
    }

    private static DataSource createDataSource() {
        PGSimpleDataSource ds = new PGSimpleDataSource();
        ds.setUrl(postgres.getJdbcUrl());
        ds.setUser(postgres.getUsername());
        ds.setPassword(postgres.getPassword());
        return ds;
    }

    private String extractId(String json) {
        return json.split("\"id\":")[1].split(",")[0];
    }
}

